create or replace function public.jobs_trade_owner() returns trigger language plpgsql security definer set search_path to 'public' as $fn$ begin if auth.uid() is null then return new; end if; if new.trade is distinct from old.trade then new.trade_locked := true; new.trade_source := 'tradedesk'; if new.trades is not distinct from old.trades then new.trades := case when new.trade = 'combo' then (case when cardinality(old.trades) > 1 then old.trades else array['combo'] end) else array[new.trade] end; end if; end if; return new; end $fn$;
create trigger jobs_trade_owner before update of trade on public.jobs for each row execute function public.jobs_trade_owner();;
